alter table public.profiles add column if not exists joining_date date, add column if not exists phone text, add column if not exists emergency_contact jsonb, add column if not exists address jsonb, add column if not exists login_enabled boolean not null default true;
alter table public.attendance add column if not exists break_minutes integer not null default 0, add column if not exists notes text;
create table if not exists public.attendance_breaks (id uuid primary key default gen_random_uuid(), attendance_id uuid not null references public.attendance(id) on delete cascade, started_at timestamptz not null default now(), ended_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.task_comments (id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade, author_id uuid not null references public.profiles(id), body text not null, created_at timestamptz not null default now());
create table if not exists public.task_attachments (id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade, storage_path text not null, file_name text not null, created_at timestamptz not null default now());
alter table public.attendance_breaks enable row level security; alter table public.task_comments enable row level security; alter table public.task_attachments enable row level security; alter table public.documents enable row level security; alter table public.announcements enable row level security;
drop policy if exists "breaks own or hierarchy" on public.attendance_breaks; create policy "breaks own or hierarchy" on public.attendance_breaks for all to authenticated using(exists(select 1 from public.attendance a where a.id=attendance_id and (a.profile_id=auth.uid() or public.is_management() or (public.current_role()='general_manager' and public.in_management_tree(a.profile_id))))) with check(exists(select 1 from public.attendance a where a.id=attendance_id and (a.profile_id=auth.uid() or public.is_management() or (public.current_role()='general_manager' and public.in_management_tree(a.profile_id)))));
drop policy if exists "comments visible to task audience" on public.task_comments; create policy "comments visible to task audience" on public.task_comments for all to authenticated using(exists(select 1 from public.tasks t where t.id=task_id and (t.assignee_id=auth.uid() or public.is_management() or public.in_management_tree(t.assignee_id)))) with check(author_id=auth.uid());
drop policy if exists "attachments visible to task audience" on public.task_attachments; create policy "attachments visible to task audience" on public.task_attachments for select to authenticated using(exists(select 1 from public.tasks t where t.id=task_id and (t.assignee_id=auth.uid() or public.is_management() or public.in_management_tree(t.assignee_id))));
drop policy if exists "documents visible to signed in" on public.documents; create policy "documents visible to signed in" on public.documents for select to authenticated using(true);
drop policy if exists "announcements visible to signed in" on public.announcements; create policy "announcements visible to signed in" on public.announcements for select to authenticated using(true);
insert into storage.buckets(id,name,public) values ('employee-documents','employee-documents',false) on conflict(id) do nothing;
drop policy if exists "employee document uploads" on storage.objects; create policy "employee document uploads" on storage.objects for insert to authenticated with check(bucket_id='employee-documents' and owner_id=auth.uid()::text);
drop policy if exists "employee document downloads" on storage.objects; create policy "employee document downloads" on storage.objects for select to authenticated using(bucket_id='employee-documents');
